window.docContents[94].resolve({"/3___-General-results-of-representation-theory/3___4___-Filtrations/Filtration-of-a-representation/#Chapter3___Definition3___4___1":{"contents":"Definition 3.4.1. A (finite) filtration of V is a sequence of subrepresentations 0 = V_0 \\subset V_1 \\subset \\cdots \\subset V_n = V.\n\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.4. Filtrations\tFiltration of a representation","header":"Filtration of a representation","id":"/3___-General-results-of-representation-theory/3___4___-Filtrations/Filtration-of-a-representation/#Chapter3___Definition3___4___1"},"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Proof-of-Corollary-2___3___10/#Chapter2___Discussion_proof_Corollary2___3___10":{"contents":"Proof. Let \\lambda be an eigenvalue of \\phi (a root of the characteristic polynomial of \\phi). It exists since k is an algebraically closed field. Then the operator \\phi - \\lambda \\operatorname{Id} is an intertwining operator V \\to V, which is not an isomorphism (since its determinant is zero). Thus by Proposition 2.3.9 this operator is zero, hence the result. \\square\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.3. Representations\tProof of Corollary 2.3.10","header":"Proof of Corollary 2.3.10","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Proof-of-Corollary-2___3___10/#Chapter2___Discussion_proof_Corollary2___3___10"}});
